"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { Checkbox } from "./checkbox";
import { useControllableState } from "../lib/hooks";

export interface SelectableItem {
  id: string;
  title: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
  /** Kleurtoon van het icoonvlakje. */
  tone?: "accent" | "green" | "amber" | "red" | "blue" | "violet" | "neutral";
  disabled?: boolean;
}

export interface SelectableGridProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect" | "onChange"> {
  items: SelectableItem[];
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** Aangeklikt item openen in plaats van selecteren. */
  onOpen?: (item: SelectableItem) => void;
  /** Kolommen per breekpunt, bv. { 0: 2, 640: 3 }. */
  columns?: number | Record<number, number>;
  /** Balk met bulkacties onderaan zodra er iets geselecteerd is. */
  actions?: React.ReactNode;
  /** Label op de standaardknop in de balk. */
  actionLabel?: (count: number) => React.ReactNode;
  onAction?: (ids: string[]) => void;
  /** Tint van de actiebalk. */
  actionTone?: "accent" | "red" | "violet";
  /** Alles-selecteren-vinkje boven het raster. */
  showSelectAll?: boolean;
  selectAllLabel?: string;
  emptyTitle?: React.ReactNode;
  emptyDescription?: React.ReactNode;
  emptyIcon?: React.ReactNode;
}

/**
 * SelectableGrid — raster van kaarten die je aanvinkt, met een balk die
 * verschijnt zodra er iets geselecteerd is. De balk zweeft onder het raster en
 * verdwijnt weer zodra de selectie leeg is.
 */
export const SelectableGrid = React.forwardRef<HTMLDivElement, SelectableGridProps>(
  function SelectableGrid(
    {
      items,
      selected,
      defaultSelected,
      onSelectedChange,
      onOpen,
      columns = { 0: 2, 640: 3 },
      actions,
      actionLabel = (aantal) => `${aantal} item${aantal === 1 ? "" : "s"} verwijderen`,
      onAction,
      actionTone = "accent",
      showSelectAll,
      selectAllLabel = "Alles selecteren",
      emptyTitle = "Niets meer over",
      emptyDescription,
      emptyIcon,
      className,
      style,
      ...rest
    },
    ref
  ) {
    const [keuze, setKeuze] = useControllableState<string[]>({
      value: selected,
      defaultValue: defaultSelected ?? [],
      onChange: onSelectedChange,
    });

    const kiesbaar = items.filter((item) => !item.disabled).map((item) => item.id);
    const allesAan = kiesbaar.length > 0 && kiesbaar.every((id) => keuze.includes(id));
    const sommige = !allesAan && kiesbaar.some((id) => keuze.includes(id));

    const wissel = (id: string) =>
      setKeuze(keuze.includes(id) ? keuze.filter((item) => item !== id) : [...keuze, id]);

    /* Breekpunten naar een media-onafhankelijke grid-variabele. */
    const kolomStijl = React.useMemo<React.CSSProperties>(() => {
      if (typeof columns === "number") {
        return { ["--lui-selgrid-cols" as string]: columns };
      }
      const punten = Object.keys(columns).map(Number).sort((a, b) => a - b);
      return { ["--lui-selgrid-cols" as string]: columns[punten[0]] ?? 2 };
    }, [columns]);

    const breekpunten =
      typeof columns === "number"
        ? []
        : Object.entries(columns)
            .map(([punt, aantal]) => [Number(punt), aantal] as const)
            .filter(([punt]) => punt > 0)
            .sort((a, b) => a[0] - b[0]);

    const eigenId = React.useId().replace(/:/g, "");

    return (
      <div ref={ref} className={cn("lui-selgrid", className)} style={{ ...style, ...kolomStijl }} {...rest}>
        {breekpunten.length > 0 && (
          <style>
            {breekpunten
              .map(
                ([punt, aantal]) =>
                  `@media (min-width:${punt}px){[data-selgrid="${eigenId}"]{--lui-selgrid-cols:${aantal}}}`
              )
              .join("")}
          </style>
        )}

        {showSelectAll && items.length > 0 && (
          <div className="lui-selgrid-head">
            <Checkbox
              checked={allesAan}
              indeterminate={sommige}
              onChange={() => setKeuze(allesAan ? [] : kiesbaar)}
              label={selectAllLabel}
              size="sm"
            />
            {keuze.length > 0 && (
              <button type="button" className="lui-selgrid-deselect" onClick={() => setKeuze([])}>
                Selectie opheffen
              </button>
            )}
          </div>
        )}

        {items.length === 0 ? (
          <div className="lui-selgrid-empty">
            <span className="lui-selgrid-empty-icon">{emptyIcon ?? <Icon name="checkCircle" size={20} />}</span>
            <p className="lui-selgrid-empty-title">{emptyTitle}</p>
            {emptyDescription && <p className="lui-selgrid-empty-desc">{emptyDescription}</p>}
          </div>
        ) : (
          <div className="lui-selgrid-items" data-selgrid={eigenId}>
            {items.map((item) => {
              const aan = keuze.includes(item.id);
              return (
                <div
                  key={item.id}
                  className="lui-selgrid-card"
                  data-selected={aan ? "" : undefined}
                  data-disabled={item.disabled ? "" : undefined}
                  data-tone={item.tone}
                >
                  <Checkbox
                    className="lui-selgrid-check"
                    checked={aan}
                    disabled={item.disabled}
                    onChange={() => wissel(item.id)}
                    aria-label={typeof item.title === "string" ? item.title : "Item selecteren"}
                  />
                  <button
                    type="button"
                    className="lui-selgrid-body"
                    disabled={item.disabled}
                    onClick={() => (onOpen ? onOpen(item) : wissel(item.id))}
                  >
                    <span className="lui-selgrid-icon">{item.icon ?? <Icon name="folder" size={18} />}</span>
                    <span className="lui-selgrid-title">{item.title}</span>
                    {item.description && <span className="lui-selgrid-desc">{item.description}</span>}
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {keuze.length > 0 && (
          <div className="lui-selgrid-bar" data-tone={actionTone} role="region" aria-label="Bulkacties">
            {actions ?? (
              <button
                type="button"
                className="lui-selgrid-action"
                onClick={() => {
                  onAction?.(keuze);
                  setKeuze([]);
                }}
              >
                <Icon name="trash" size={15} />
                {actionLabel(keuze.length)}
              </button>
            )}
          </div>
        )}
      </div>
    );
  }
);

/* ========================= SelectableGrid ========================= */
.lui-selgrid { --lui-selgrid-cols: 2; display: grid; gap: 12px; width: 100%; }

.lui-selgrid-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.lui-selgrid-deselect {
  border: 0; background: transparent; color: var(--text-3);
  font: inherit; font-size: var(--fs-sm); cursor: pointer;
}
.lui-selgrid-deselect:hover { color: var(--text); text-decoration: underline; }
.lui-selgrid-deselect:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-selgrid-items {
  display: grid; gap: 10px;
  grid-template-columns: repeat(var(--lui-selgrid-cols), minmax(0, 1fr));
}

.lui-selgrid-card {
  position: relative; display: grid;
  border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface);
  transition: border-color var(--dur-fast), background var(--dur-fast), transform var(--dur-fast);
}
.lui-selgrid-card:hover { border-color: var(--border-strong); transform: translateY(-1px); }
.lui-selgrid-card[data-selected] {
  border-color: var(--accent);
  background: color-mix(in oklab, var(--accent) 7%, var(--surface));
}
.lui-selgrid-card[data-disabled] { opacity: .5; }
.lui-selgrid-card[data-disabled]:hover { transform: none; border-color: var(--border); }

.lui-selgrid-check { position: absolute; top: 9px; inset-inline-start: 9px; z-index: 1; }

.lui-selgrid-body {
  display: grid; gap: 4px; justify-items: center; text-align: center;
  padding: 26px 12px 14px; border: 0; border-radius: inherit;
  background: transparent; color: inherit; font: inherit; cursor: pointer;
}
.lui-selgrid-body:disabled { cursor: default; }
.lui-selgrid-body:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-selgrid-icon {
  display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 4px;
  border-radius: var(--r-sm); background: var(--surface-3); color: var(--text-2);
}
.lui-selgrid-card[data-tone="accent"] .lui-selgrid-icon { background: color-mix(in oklab, var(--accent) 14%, transparent); color: var(--accent); }
.lui-selgrid-card[data-tone="green"] .lui-selgrid-icon { background: color-mix(in oklab, var(--green) 14%, transparent); color: var(--green); }
.lui-selgrid-card[data-tone="amber"] .lui-selgrid-icon { background: color-mix(in oklab, var(--amber) 16%, transparent); color: var(--amber); }
.lui-selgrid-card[data-tone="red"] .lui-selgrid-icon { background: color-mix(in oklab, var(--red) 14%, transparent); color: var(--red); }
.lui-selgrid-card[data-tone="blue"] .lui-selgrid-icon { background: color-mix(in oklab, var(--blue) 14%, transparent); color: var(--blue); }
.lui-selgrid-card[data-tone="violet"] .lui-selgrid-icon { background: color-mix(in oklab, var(--violet) 14%, transparent); color: var(--violet); }

.lui-selgrid-title { font-size: var(--fs-sm); font-weight: 600; color: var(--text); }
.lui-selgrid-desc { font-size: 12px; color: var(--text-3); }

/* actiebalk */
.lui-selgrid-bar {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  padding: 8px; border-radius: var(--r-full);
  background: var(--accent); color: var(--accent-fg);
  box-shadow: var(--sh-lg);
  animation: lui-selgrid-bar var(--dur) var(--ease-out);
}
.lui-selgrid-bar[data-tone="red"] { background: var(--red); color: #fff; }
.lui-selgrid-bar[data-tone="violet"] { background: var(--violet); color: #fff; }

.lui-selgrid-action {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 14px; border: 0; border-radius: var(--r-full);
  background: transparent; color: inherit;
  font: inherit; font-size: var(--fs-sm); font-weight: 650; cursor: pointer;
  transition: background var(--dur-fast);
}
.lui-selgrid-action:hover { background: rgba(255, 255, 255, .18); }
.lui-selgrid-action:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }

.lui-selgrid-empty {
  display: grid; justify-items: center; gap: 4px; padding: 34px 16px;
  border: 1px dashed var(--border-strong); border-radius: var(--r-md);
}
.lui-selgrid-empty-icon {
  display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 6px;
  border-radius: 50%; background: color-mix(in oklab, var(--green) 14%, transparent); color: var(--green);
}
.lui-selgrid-empty-title { margin: 0; font-size: var(--fs-sm); font-weight: 650; color: var(--text); }
.lui-selgrid-empty-desc { margin: 0; font-size: 12.5px; color: var(--text-3); }

@keyframes lui-selgrid-bar {
  from { opacity: 0; transform: translateY(10px) scale(.96); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .lui-selgrid-card:hover { transform: none; }
  .lui-selgrid-bar { animation: none; }
}
